# Generates Skins\Mixdock\Rows.inc: the pool of app row slots. Rainmeter cannot create meters at runtime,
# so the skin has a fixed number of identical rows that Mixer.lua fills, shows and hides.
# Run it after changing the row structure below, then commit the generated file. Positions and sizes are not
# in here: they are variables from Layout-full.inc and Layout-compact.inc.
#
# A row, left to right: a gutter (pin button on top, reorder grip below), the app icon, then the name,
# percentage and mute button on top of the volume slider.

$rows = 6

$out = New-Object Text.StringBuilder
[void]$out.AppendLine('; Rows.inc - the pool of app row slots. Mixer.lua fills and shows or hides them.')
[void]$out.AppendLine('; Generated by tools\generate-rows.ps1: the rows are identical except for their number and position.')
[void]$out.AppendLine('; Every position comes from the layout file in use (Layout-full.inc or Layout-compact.inc).')
[void]$out.AppendLine('')

# design y of a row's top edge plus a layout variable, scaled
function RowY($n, $variable) { return "((#RowsTop#+$($n - 1)*#RowH#+#$variable#)*#Scale#)" }

for ($n = 1; $n -le $rows; $n++) {
    $mouseDown = '$MouseX:%$'
    $row = @"
; ---------- Row $n ----------

[R${n}Tile]
Meter=Shape
MeterStyle=StTile
Y=$(RowY $n 'TileY')
Shape=Rectangle 0,0,(#TileSize#*#Scale#),(#TileSize#*#Scale#),(#TileSize#/4*#Scale#) | Fill Color #R${n}Tile# | StrokeWidth 0
Group=R${n}Tile

[R${n}Letter]
Meter=String
MeterStyle=StLetter
Y=$(RowY $n 'LetterY')
Group=R${n}Tile

[R${n}Img]
Meter=Image
MeterStyle=StImg
Y=$(RowY $n 'ImgY')
Group=R${n}Img

; Pin button (gutter, top): grey and translucent when the app is not pinned, bright when it is. Mixer.lua sets the color.
[R${n}PinGlyph]
Meter=String
MeterStyle=StPinGlyph
Text=#IconPin#
Y=$(RowY $n 'PinGlyphY')
Group=R${n}Pin

[R${n}PinHit]
Meter=Shape
MeterStyle=StGutterHit
Y=$(RowY $n 'PinHitY')
Shape=Rectangle 0,0,(#Gutter#*#Scale#),(#PinHitH#*#Scale#) | Fill Color 0,0,0,1 | StrokeWidth 0
MouseOverAction=[!CommandMeasure Mixer "PinHover($n,1)"]
MouseLeaveAction=[!CommandMeasure Mixer "PinHover($n,0)"]
LeftMouseDownAction=[!CommandMeasure Mixer "Down('pin',$n)"]
LeftMouseUpAction=[!CommandMeasure Mixer "Click('pin',$n)"]
Group=R${n}Pin

; Reorder grip (gutter, below the pin): faint, a little more visible on hover. Dragging it moves the app inside its group.
[R${n}Grab]
Meter=Shape
MeterStyle=StGutterHit
Y=$(RowY $n 'GrabY')
Shape=Rectangle 0,0,(#Gutter#*#Scale#),(#GrabHitH#*#Scale#) | Fill Color 0,0,0,1 | StrokeWidth 0
Shape2=Rectangle ((#Gutter#-#GrabBarW#)/2*#Scale#),((#GrabHitH#-#GrabBarH#)/2*#Scale#),(#GrabBarW#*#Scale#),(#GrabBarH#*#Scale#),(3*#Scale#) | Fill Color #R${n}Grab# | StrokeWidth 0
MouseOverAction=[!CommandMeasure Mixer "GrabHover($n,1)"]
MouseLeaveAction=[!CommandMeasure Mixer "GrabHover($n,0)"]
LeftMouseDownAction=[!CommandMeasure Mixer "Reorder($n)"]
Group=R${n}Grab

[R${n}Name]
Meter=String
MeterStyle=StName
Y=$(RowY $n 'NameY')
MouseScrollUpAction=[!CommandMeasure Mixer "Wheel($n,1)"]
MouseScrollDownAction=[!CommandMeasure Mixer "Wheel($n,-1)"]
Group=R${n}

[R${n}Percent]
Meter=String
MeterStyle=StPercent
Y=$(RowY $n 'PercentY')
MouseScrollUpAction=[!CommandMeasure Mixer "Wheel($n,1)"]
MouseScrollDownAction=[!CommandMeasure Mixer "Wheel($n,-1)"]
Group=R${n}

[R${n}Slider]
Meter=Shape
MeterStyle=StSlider
Y=$(RowY $n 'SliderY')
Shape=Rectangle 0,0,(#SliderW#*#Scale#),(6*#Scale#),(3*#Scale#) | Fill Color #R${n}Track# | StrokeWidth 0
Shape2=Rectangle 0,0,(#SliderW#*#Scale#*#R${n}Vol#/100),(6*#Scale#),(3*#Scale#) | Fill Color #R${n}Fill# | StrokeWidth 0
Shape3=Ellipse (#SliderW#*#Scale#*#R${n}Vol#/100),(3*#Scale#),(7*#Scale#) | Fill Color #R${n}Thumb# | StrokeWidth 0
Group=R${n}

; Invisible hit area over the track: a press sets the value, the helper then follows the drag.
[R${n}Hit]
Meter=Shape
MeterStyle=StHit
Y=$(RowY $n 'HitY')
LeftMouseDownAction=[!CommandMeasure Mixer "Press($n,$mouseDown)"]
MouseScrollUpAction=[!CommandMeasure Mixer "Wheel($n,1)"]
MouseScrollDownAction=[!CommandMeasure Mixer "Wheel($n,-1)"]
Group=R${n}Hit

[R${n}Mute]
Meter=String
MeterStyle=StMute
Y=$(RowY $n 'MuteY')
LeftMouseDownAction=[!CommandMeasure Mixer "Down('mute',$n)"]
LeftMouseUpAction=[!CommandMeasure Mixer "Click('mute',$n)"]
MouseLeaveAction=[!CommandMeasure Mixer "Cancel()"]
Group=R${n}


"@
    [void]$out.Append($row)
}

$target = Join-Path (Split-Path -Parent $PSScriptRoot) 'Skins\Mixdock\Rows.inc'
[IO.File]::WriteAllText($target, $out.ToString().TrimEnd() + "`r`n", (New-Object Text.UTF8Encoding $false))
Write-Host "Wrote $target"
